import{_ as o,o as a,c as e,ag as _}from"./chunks/framework.B5ULsuav.js";const d=JSON.parse('{"title":"金刚经4分-布施的分寸","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经4分-布施的分寸.md","filePath":"60-原文段落/金刚经4分-布施的分寸.md","lastUpdated":1778155802000}'),r={name:"60-原文段落/金刚经4分-布施的分寸.md"};function p(u,t,s,n,q,c){return a(),e("div",null,[...t[0]||(t[0]=[_('<h1 id="金刚经4分-布施的分寸" tabindex="-1">金刚经4分-布施的分寸 <a class="header-anchor" href="#金刚经4分-布施的分寸" aria-label="Permalink to &quot;金刚经4分-布施的分寸&quot;">​</a></h1><blockquote><p>来源：<a href="/liaokongjushi-wisdom/01-Raw-Sources/4了空居士讲《金刚经》-第四分妙行无住分20160916">4了空居士讲《金刚经》-第四分妙行无住分20160916</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>【答疑】</strong></p><p>**4.问：**今天第四分说到&quot;不住色布施&quot;，我就想起在第一分里又说到&quot;次第乞已&quot;，这时候是不区分贫富都依次地进行乞食，我就想到，有时候我们在路上碰到一些乞丐，那我们有看一下，有区别一下这是真的还是假的，然后根据情况根据自己判断去进行这种布施吧，那么这个是算是&quot;不住色&quot;还是&quot;住&quot;了&quot;色&quot;呢？</p><p>**了空居士：**噢，我告诉你，你们看一下吧，你们真的看得准吗？你们可能说了空居士，那如果你在路上遇到乞丐跟你讨钱，你怎么给呢？啊，我也看不见，我就按照给乞丐的标准给他。现在我们中堂这边很少有乞丐了。我们从前吧，就是说如果前几年有乞丐的时候，我给他们的钱最多是给他五毛钱，我很少给他们一块钱。我觉得乞丐按照这十年前我给的五毛就差不多了，我不会给他五块钱，更不会给他五十元或者一百元。他们也不敢说我给的少嘛，讨饭就是这样啊，一天都是人家来跟我讨，我就给这个五毛钱嘛，就是我心中对你们这些讨饭的人的一个标准嘛，是不是啊？其实他们讨饭，如果一天你一个人给他五毛，十个人给他五块，一百个人给他五十元，他们也要一天真的要讨一百个人也很难，是不是啊？一天如果讨到二十个人，他也可以度得一天了嘛，是不是？所以我按照我自己我给他这个标准，然后我就不管它真还是假的，假的我也给五毛,反正这个讨饭的工作也不是那么好做的嘛，哈哈，我就不用去想。</p><p>但是曾经有个人就过来跟我说，唉呀老板，我的钱包丢了，你给我二十块钱去坐车等等，我说我就给不到啦。我说，我也故意说一天有好几个这么丢了钱包的人都要我给二十块钱，我怎么那么多钱啊，假如你是求助的，你到拐弯那居委会去吧，或者是到民政局去吧，如果你是讨饭的，我只能给你五毛钱，你自己定位了,如果求帮助的，我们拐弯那正好有个居委会，你去那里看一下居委会能不能给你怎么帮助，我个人就没这个能力，所以他也拿我没办法了。</p><p>**主持：**我记得前一段时间嘛，我们在网上看到有的同修的亲戚有一些困难，那有的就布施的钱就多了一些，那么我们有时候在路上见到这些有困难的，我们可能就不了解情况，我们就布施的少一些，那这算是&quot;住色布施&quot;吗？</p><p>**了空居士：**这个问题问得非常好。你知道他确实有困难，所以我们会给比较大一点的帮助，我们不了解，给他小一点帮助。这个其实这个也是&quot;不住色布施&quot;，也是最客观的心嘛。因为你了解，你就这么做吧，你不了解，你就那样做嘛。</p><p>那么你说反过来那些在路上求助的人不是很吃亏吗？不会吃亏啊，他可以去找慈善部门帮他们搞出一个信任度嘛，是不是啊？这是他自己的方法不对。好像明树你去买黄金，你肯定问他一克多少钱啊，如果你去买大米，你就问他一斤多少钱啊。你不会说一克大米多少钱，你不问这些东西的，是不是啊？所以说他们在路边的，方法不对啊，他们为什么不去找记者找谁帮他们广告一下呢？是不是？所以我们这个也叫做清净心，我不了解，就是说不了解。孔子不是有一句名言&quot;知之为知之，不知为不知&quot;啊。所以你们平等心一定要记得大米一斤多少钱，黄金一克多少钱，不能以买大米的价格去买黄金，也不能以买黄金的价格去买大米，是不是啊，这才叫平等心，你要对得住这个东西的价值和价格，哈哈，你不了解，不能给他多钱啊，你了解了，才能给他多钱。</p>',10)])])}const l=o(r,[["render",p]]);export{d as __pageData,l as default};
